// Find elements that overflow the viewport width
const vw = document.documentElement.clientWidth;
const overflowing = [];
document.querySelectorAll('*').forEach(el => {
  const rect = el.getBoundingClientRect();
  if (rect.right > vw + 5) {
    overflowing.push({
      tag: el.tagName,
      class: el.className,
      id: el.id,
      width: rect.width,
      right: rect.right,
      viewportWidth: vw,
      overflow: rect.right - vw,
      parentClass: el.parentElement ? el.parentElement.className : null
    });
  }
});
return JSON.stringify(overflowing.slice(0, 30), null, 2);

// Find the project cards container - look for flex/grid containers with multiple children
const vw = document.documentElement.clientWidth;
const containers = [];
document.querySelectorAll('*').forEach(el => {
  const style = getComputedStyle(el);
  const rect = el.getBoundingClientRect();
  if ((style.display === 'flex' || style.display === 'grid' || style.display === 'inline-flex') && el.children.length > 2 && rect.width > vw * 0.5) {
    containers.push({
      tag: el.tagName,
      class: el.className,
      display: style.display,
      flexWrap: style.flexWrap,
      gap: style.gap,
      width: rect.width,
      right: rect.right,
      overflow: style.overflow,
      overflowX: style.overflowX,
      children: el.children.length,
      childrenOverflow: Array.from(el.children).filter(c => c.getBoundingClientRect().right > vw).length,
      textPreview: el.textContent.substring(0, 100)
    });
  }
});
return JSON.stringify(containers, null, 2);

// Get the flex container and its children details
const vw = document.documentElement.clientWidth;
let flexContainer = null;
document.querySelectorAll('*').forEach(el => {
  const style = getComputedStyle(el);
  if (style.display === 'flex' && el.children.length === 8 && el.textContent.includes('Frontend Redesign')) {
    flexContainer = el;
  }
});

if (!flexContainer) return 'not found';

const style = getComputedStyle(flexContainer);
const rect = flexContainer.getBoundingClientRect();
const parentStyle = getComputedStyle(flexContainer.parentElement);
const parentRect = flexContainer.parentElement.getBoundingClientRect();

const result = {
  container: {
    tag: flexContainer.tagName,
    display: style.display,
    flexWrap: style.flexWrap,
    flexDirection: style.flexDirection,
    gap: style.gap,
    overflow: style.overflow,
    overflowX: style.overflowX,
    width: rect.width,
    left: rect.left,
    right: rect.right,
    padding: style.padding,
    margin: style.margin,
    maxWidth: style.maxWidth,
    boxSizing: style.boxSizing,
  },
  parent: {
    tag: flexContainer.parentElement.tagName,
    display: parentStyle.display,
    overflow: parentStyle.overflow,
    overflowX: parentStyle.overflowX,
    width: parentRect.width,
    right: parentRect.right,
    padding: parentStyle.padding,
  },
  children: Array.from(flexContainer.children).map((c, i) => {
    const cs = getComputedStyle(c);
    const cr = c.getBoundingClientRect();
    return {
      index: i,
      tag: c.tagName,
      width: cr.width,
      left: cr.left,
      right: cr.right,
      flexShrink: cs.flexShrink,
      flexGrow: cs.flexGrow,
      flexBasis: cs.flexBasis,
      minWidth: cs.minWidth,
      maxWidth: cs.maxWidth,
      overflow: cr.right > vw,
      textPreview: c.textContent.substring(0, 30)
    };
  }),
  viewportWidth: vw
};

return JSON.stringify(result, null, 2);

// Card index 2 is 478px wide while others are 100-180px. Check its content.
const vw = document.documentElement.clientWidth;
let flexContainer = null;
document.querySelectorAll('*').forEach(el => {
  const style = getComputedStyle(el);
  if (style.display === 'flex' && el.children.length === 8 && el.textContent.includes('Frontend Redesign')) {
    flexContainer = el;
  }
});

const card = flexContainer.children[2];
const cardHTML = card.innerHTML;
const cardText = card.textContent;

// Check if there's a long unbroken word or string
// Check the card's inner structure
const innerElements = Array.from(card.querySelectorAll('*')).map(el => {
  const cs = getComputedStyle(el);
  const cr = el.getBoundingClientRect();
  return {
    tag: el.tagName,
    text: el.textContent.substring(0, 80),
    width: cr.width,
    whiteSpace: cs.whiteSpace,
    overflow: cs.overflow,
    textOverflow: cs.textOverflow,
    wordBreak: cs.wordBreak,
    overflowWrap: cs.overflowWrap,
  };
}).filter(e => e.width > 200);

return JSON.stringify({
  cardText: cardText,
  cardHTMLLength: cardHTML.length,
  innerElements
}, null, 2);

// The title div has white-space: nowrap. Let's confirm this is on the title element specifically
// and check if the card has min-width: auto (which prevents flex items from shrinking below content size)
let flexContainer = null;
document.querySelectorAll('*').forEach(el => {
  const style = getComputedStyle(el);
  if (style.display === 'flex' && el.children.length === 8 && el.textContent.includes('Frontend Redesign')) {
    flexContainer = el;
  }
});

const card = flexContainer.children[2];
const titleDiv = card.querySelector('*'); // first child element

// Get the full chain of styles
const cardStyle = getComputedStyle(card);

// Check all cards' titles for white-space
const titleInfo = Array.from(flexContainer.children).map((c, i) => {
  // Find the title element (first text element)
  const firstDiv = c.querySelector('div');
  if (!firstDiv) return { index: i, noDiv: true };
  const s = getComputedStyle(firstDiv);
  return {
    index: i,
    titleText: firstDiv.textContent.substring(0, 60),
    whiteSpace: s.whiteSpace,
    titleWidth: firstDiv.getBoundingClientRect().width,
    cardWidth: c.getBoundingClientRect().width,
    cardMinWidth: cardStyle.minWidth,
  };
});

return JSON.stringify(titleInfo, null, 2);

// Calculate total width needed vs available
const totalCardWidths = 177 + 136 + 478 + 120 + 146 + 131 + 142 + 104;
const gaps = 7 * 16; // 7 gaps at 16px
const containerAvailable = 1168; // measured container width
return JSON.stringify({
  totalCardWidths,
  gaps,
  totalNeeded: totalCardWidths + gaps,
  containerWidth: containerAvailable,
  overflow: totalCardWidths + gaps - containerAvailable
});
